source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            colors = {grid[y][x] for y, x in cells}
            boxes = {}
            for color in colors:
                points = [(y, x) for y, x in cells if grid[y][x] == color]
                boxes[color] = (max(y for y, x in points)-min(y for y, x in points)+1) * (max(x for y, x in points)-min(x for y, x in points)+1)
            outer_to_inner = sorted(colors, key=lambda color: boxes[color], reverse=True)
            remap = {color: outer_to_inner[-1-i] for i, color in enumerate(outer_to_inner)}
            for y, x in cells:
                out[y][x] = remap[grid[y][x]]
    return out
'''
